import { Module } from "@nestjs/common"
import { ApolloDriver, ApolloDriverConfig } from "@nestjs/apollo"
import { GraphQLModule } from "@nestjs/graphql"

@Module({
    imports: [
        GraphQLModule.forRoot<ApolloDriverConfig>({
            driver: ApolloDriver,     // qaysi server ishlatiladi
            autoSchemaFile: true,     // sxema klass va dekoratorlardan yasaladi (code-first)
        }),
    ],
})
export class AppModule {}

GraphQLModule.forRoot<ApolloDriverConfig>({
    driver: ApolloDriver,
    typePaths: ["./**/*.graphql"],                   // SDL fayllar qayerda
    definitions: {
        path: join(process.cwd(), "src/graphql.ts"), // TypeScript tiplari shu faylga yoziladi
        outputAs: "class",
    },
})

import { Field, ID, Int, ObjectType } from "@nestjs/graphql"

@ObjectType({ description: "Retsept" })
export class Recipe {
    @Field(() => ID)              // ID — noyob identifikator (JSON'da satr)
    id: string

    @Field()                      // string -> String!
    title: string

    @Field(() => Int)             // son: Int'ni aniq aytish kerak, aks holda Float
    minutes: number

    @Field({ nullable: true })    // null bo'lishi mumkin -> String ("!" yo'q)
    note?: string

    @Field(() => [String])        // massiv: tur funksiya ichida yoziladi
    tags: string[]
}

export enum Level { EASY = "EASY", HARD = "HARD" }

registerEnumType(Level, {
    name: "Level",                       // sxemadagi nom
    description: "Qiyinlik darajasi",
})

@ObjectType()
export class Dish {
    @Field(() => Level)                  // enum'ni funksiya orqali ko'rsatamiz
    level: Level
}

query Cheap($max: Int!) {          # operatsiya turi (query), nomi (Cheap), o'zgaruvchi ($max)
    cheaperThan(max: $max) {       # Query tipidagi maydon va uning argumenti
        name                       # faqat shu ikki maydon so'ralyapti
        price
    }
}

GraphQLModule.forRoot<ApolloDriverConfig>({
    driver: ApolloDriver,
    autoSchemaFile: true,
    context: ({ req, res }) => ({ req, res, startedAt: Date.now() }),
})

