import { Module } from "@nestjs/common"
import { ApolloDriver, ApolloDriverConfig } from "@nestjs/apollo"
import { Args, GraphQLModule, Parent, Query, ResolveField, Resolver } from "@nestjs/graphql"

const authors = [{ id: 1, name: "Abdulla Qodiriy" }, { id: 2, name: "Cho'lpon" }]
const books = [
    { id: 10, title: "O'tkan kunlar", authorId: 1 },
    { id: 11, title: "Mehrobdan chayon", authorId: 1 },
    { id: 12, title: "Kecha va kunduz", authorId: 2 },
]

@Resolver("Author")                               // sxemadagi tur nomi qator sifatida
class AuthorsResolver {
    @Query("author")                              // sxemadagi Query.author maydoni
    author(@Args("id") id: number) { return authors.find(a => a.id === id) }

    @ResolveField("books")                        // Author.books maydoni
    books(@Parent() author: { id: number }) { return books.filter(b => b.authorId === author.id) }
}

@Module({
    imports: [GraphQLModule.forRoot<ApolloDriverConfig>({
        driver: ApolloDriver,
        typeDefs: `
            type Book { id: Int! title: String! }
            type Author { id: Int! name: String! books: [Book!]! }
            type Query { author(id: Int!): Author }
        `,
    })],
    providers: [AuthorsResolver],
})
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.post("/graphql", { query: "{ author(id: 1) { name books { title } } }" })
    await http.close()
}
main()

