import { Module } from "@nestjs/common"
import { ApolloDriver, ApolloDriverConfig } from "@nestjs/apollo"
import { Field, GraphQLModule, ObjectType, Query, Resolver } from "@nestjs/graphql"
import { ASTVisitor, GraphQLError, ValidationContext } from "graphql"

function depthLimit(max: number) {
    return (ctx: ValidationContext): ASTVisitor => {
        let depth = 0, reported = false
        return {
            Field: {
                enter(node) {
                    depth++
                    if (depth > max && !reported) {
                        reported = true
                        ctx.reportError(new GraphQLError(`So'rov juda chuqur: ${depth} > ${max}`, { nodes: [node] }))
                    }
                },
                leave() { depth-- },
            },
        }
    }
}

@ObjectType() class Category {
    @Field() name!: string
    @Field(() => Category, { nullable: true }) parent?: Category
}

