@ObjectType()
class Note {
    @Field(() => Int) id: number
    @Field() text: string
}

@InputType() class CreateNoteInput { @Field() text: string }
@InputType() class UpdateNoteInput extends PartialType(CreateNoteInput) {}

@Injectable()
class NotesService {
    private notes: Note[] = []
    private next = 1
    findAll() { return this.notes }
    findOne(id: number) {
        const n = this.notes.find(x => x.id === id)
        if (!n) throw new NotFoundException(`Eslatma #${id} yo'q`)
        return n
    }
    create(input: CreateNoteInput) { const n = { id: this.next++, ...input }; this.notes.push(n); return n }
    update(id: number, input: UpdateNoteInput) { return Object.assign(this.findOne(id), input) }
    remove(id: number) { const n = this.findOne(id); this.notes = this.notes.filter(x => x !== n); return true }
}

@Resolver(() => Note)
class NotesResolver {
    constructor(private readonly service: NotesService) {}
    @Query(() => [Note]) notes() { return this.service.findAll() }
    @Mutation(() => Note) createNote(@Args("input") i: CreateNoteInput) { return this.service.create(i) }
    @Mutation(() => Note) updateNote(@Args("id", { type: () => Int }) id: number, @Args("input") i: UpdateNoteInput) { return this.service.update(id, i) }
    @Mutation(() => Boolean) removeNote(@Args("id", { type: () => Int }) id: number) { return this.service.remove(id) }
}

