function BaseResolver<T>(classRef: Type<T>) {
    @Resolver({ isAbstract: true })
    class BaseResolverHost {
        protected items: T[] = []
        @Query(() => [classRef], { name: `all${classRef.name}s` }) findAll() { return this.items }
        @Query(() => Int, { name: `count${classRef.name}s` }) count() { return this.items.length }
    }
    return BaseResolverHost
}

