import { Module, Type } from "@nestjs/common"
import { ApolloDriver, ApolloDriverConfig } from "@nestjs/apollo"
import { Args, Field, GraphQLModule, Int, ObjectType, Query, Resolver } from "@nestjs/graphql"

function Paginated<T>(classRef: Type<T>) {
    @ObjectType({ isAbstract: true })
    abstract class PaginatedType {
        @Field(() => [classRef]) items!: T[]
        @Field(() => Int) total!: number
        @Field() hasMore!: boolean
    }
    return PaginatedType
}

@ObjectType() class Book { @Field() title!: string }
@ObjectType() class PaginatedBooks extends Paginated(Book) {}

const books = ["O'tkan kunlar", "Mehrobdan chayon", "Sarob", "Kecha va kunduz", "Ufq"].map(title => ({ title }))

@Resolver()
class BooksResolver {
    @Query(() => PaginatedBooks)
    books(@Args("skip", { type: () => Int, defaultValue: 0 }) skip: number, @Args("take", { type: () => Int, defaultValue: 2 }) take: number) {
        return { items: books.slice(skip, skip + take), total: books.length, hasMore: skip + take < books.length }
    }
}

@Module({ imports: [GraphQLModule.forRoot<ApolloDriverConfig>({ driver: ApolloDriver, autoSchemaFile: true })], providers: [BooksResolver] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.post("/graphql", { query: "{ books { items { title } total hasMore } }" })
    await http.post("/graphql", { query: "{ books(skip: 4) { items { title } hasMore } }" })
    await http.close()
}
main()

import { Module } from "@nestjs/common"
import { ApolloDriver, ApolloDriverConfig } from "@nestjs/apollo"
import { Args, Field, GraphQLModule, Int, ObjectType, Query, Resolver } from "@nestjs/graphql"

@ObjectType() class Dish { @Field(() => Int) id!: number; @Field() name!: string }
@ObjectType() class DishEdge { @Field() cursor!: string; @Field(() => Dish) node!: Dish }
@ObjectType() class PageInfo { @Field(() => String, { nullable: true }) endCursor!: string | null; @Field() hasNextPage!: boolean }
@ObjectType() class DishConnection { @Field(() => [DishEdge]) edges!: DishEdge[]; @Field(() => PageInfo) pageInfo!: PageInfo }

const dishes = ["Osh", "Manti", "Somsa", "Lag'mon", "Norin"].map((name, i) => ({ id: i + 1, name }))
const encode = (id: number) => Buffer.from(`dish:${id}`).toString("base64")
const decode = (cursor: string) => Number(Buffer.from(cursor, "base64").toString().split(":")[1])

@Resolver()
class DishesResolver {
    @Query(() => DishConnection)
    dishes(@Args("first", { type: () => Int }) first: number, @Args("after", { type: () => String, nullable: true }) after?: string) {
        const start = after ? dishes.findIndex(d => d.id === decode(after)) + 1 : 0
        const page = dishes.slice(start, start + first)
        return {
            edges: page.map(node => ({ cursor: encode(node.id), node })),
            pageInfo: { endCursor: page.length ? encode(page[page.length - 1].id) : null, hasNextPage: start + first < dishes.length },
        }
    }
}

@Module({ imports: [GraphQLModule.forRoot<ApolloDriverConfig>({ driver: ApolloDriver, autoSchemaFile: true })], providers: [DishesResolver] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const query = "query($after: String) { dishes(first: 2, after: $after) { edges { node { name } } pageInfo { endCursor hasNextPage } } }"
    const first = await http.post("/graphql", { query })
    await http.post("/graphql", { query, variables: { after: first.data.data.dishes.pageInfo.endCursor } })
    await http.close()
}
main()

import { Module } from "@nestjs/common"
import { ApolloDriver, ApolloDriverConfig } from "@nestjs/apollo"
import { Args, createUnionType, Field, GraphQLModule, Int, Mutation, ObjectType, Query, Resolver } from "@nestjs/graphql"

@ObjectType() class Transfer { @Field(() => Int) amount!: number; @Field() to!: string }
@ObjectType() class InsufficientFunds { @Field(() => Int) balance!: number; @Field() message!: string }

const TransferResult = createUnionType({
    name: "TransferResult",
    types: () => [Transfer, InsufficientFunds] as const,
    resolveType: (value: object) => ("to" in value ? Transfer : InsufficientFunds),
})

let balance = 100_000
@Resolver()
class WalletResolver {
    @Query(() => Int) balance() { return balance }
    @Mutation(() => TransferResult) transfer(@Args("amount", { type: () => Int }) amount: number) {
        if (amount > balance) return { balance, message: "Mablag' yetarli emas" }
        balance -= amount
        return { amount, to: "Vali" }
    }
}

@Module({ imports: [GraphQLModule.forRoot<ApolloDriverConfig>({ driver: ApolloDriver, autoSchemaFile: true })], providers: [WalletResolver] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const q = (n: number) => `mutation { transfer(amount: ${n}) { __typename ... on Transfer { amount to } ... on InsufficientFunds { balance message } } }`
    await http.post("/graphql", { query: q(70_000) })
    await http.post("/graphql", { query: q(50_000) })
    await http.close()
}
main()

import { CanActivate, ExecutionContext, Injectable, Module, UseGuards } from "@nestjs/common"
import { Reflector } from "@nestjs/core"
import { ApolloDriver, ApolloDriverConfig } from "@nestjs/apollo"
import { GqlExecutionContext, GraphQLModule, Int, Query, Resolver } from "@nestjs/graphql"

const Roles = Reflector.createDecorator<string[]>()

@Injectable()
class RolesGuard implements CanActivate {
    constructor(private readonly reflector: Reflector) {}
    canActivate(ctx: ExecutionContext) {
        const roles = this.reflector.get(Roles, ctx.getHandler())
        if (!roles) return true
        const req = GqlExecutionContext.create(ctx).getContext().req
        return roles.includes(req.headers["x-role"])
    }
}

@Resolver()
@UseGuards(RolesGuard)
class StatsResolver {
    @Query(() => Int) visitors() { return 1520 }
    @Roles(["admin"]) @Query(() => Int) revenue() { return 9_450_000 }
}

