import { Module } from "@nestjs/common"
import { ApolloDriver, ApolloDriverConfig } from "@nestjs/apollo"
import { Args, Field, GraphQLModule, Int, Mutation, ObjectType, Query, Resolver, Subscription } from "@nestjs/graphql"
import { PubSub } from "graphql-subscriptions"
import { createClient } from "graphql-ws"

@ObjectType()
class Comment {
    @Field(() => Int) id: number
    @Field() text: string
    @Field(() => Int) postId: number
}

const pubSub = new PubSub()
let markSubscribed!: () => void
const subscribed = new Promise<void>(resolve => (markSubscribed = resolve))

@Resolver(() => Comment)
class CommentsResolver {
    private nextId = 1
    @Query(() => Int) commentsCount() { return this.nextId - 1 }

    @Mutation(() => Comment)
    async addComment(@Args("postId", { type: () => Int }) postId: number, @Args("text") text: string) {
        const comment = { id: this.nextId++, text, postId }
        await pubSub.publish("commentAdded", { commentAdded: comment })   // kalit = subscription nomi
        return comment
    }

    @Subscription(() => Comment, {
        filter: (payload, variables) => payload.commentAdded.postId === variables.postId,
    })
    commentAdded(@Args("postId", { type: () => Int }) postId: number) {
        const iterator = pubSub.asyncIterableIterator("commentAdded")
        setImmediate(markSubscribed)                                      // obuna tayyor
        return iterator
    }
}

@Module({
    imports: [GraphQLModule.forRoot<ApolloDriverConfig>({
        driver: ApolloDriver,
        autoSchemaFile: true,
        subscriptions: { "graphql-ws": true },
    })],
    providers: [CommentsResolver],
})
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const url = (await http.app.getUrl()).replace("http", "ws") + "/graphql"
    const client = createClient({ url, webSocketImpl: WebSocket })
    const received: string[] = []
    const done = new Promise<void>((resolve, reject) => {
        client.subscribe(
            { query: "subscription ($postId: Int!) { commentAdded(postId: $postId) { id text } }", variables: { postId: 7 } },
            { next: msg => { received.push(JSON.stringify(msg.data)); if (received.length === 2) resolve() }, error: reject, complete: () => {} },
        )
    })
    await subscribed
    await http.post("/graphql", { query: 'mutation { addComment(postId: 7, text: "Zo\'r maqola") { id } }' })
    await http.post("/graphql", { query: 'mutation { addComment(postId: 9, text: "Boshqa post") { id } }' })
    await http.post("/graphql", { query: 'mutation { addComment(postId: 7, text: "Rahmat") { id } }' })
    await done
    console.log(received.join("\n"))
    await client.dispose()
    await http.close()
}
main()

