import { CanActivate, ExecutionContext, Injectable, Module, UseGuards } from "@nestjs/common"
import { ApolloDriver, ApolloDriverConfig } from "@nestjs/apollo"
import { Field, GraphQLModule, ObjectType, Parent, Query, ResolveField, Resolver } from "@nestjs/graphql"

const calls: string[] = []

@Injectable()
class LogGuard implements CanActivate {
    canActivate(ctx: ExecutionContext) { calls.push(ctx.getHandler().name); return true }
}

@ObjectType() class User { @Field() name: string }

@Resolver(() => User)
@UseGuards(LogGuard)
class UsersResolver {
    @Query(() => User) me() { return { name: "Ali" } }
    @ResolveField(() => String) email(@Parent() u: User) { return `${u.name.toLowerCase()}@mail.uz` }
}

function makeModule(enhancers: ("guards" | "interceptors" | "filters")[]) {
    @Module({
        imports: [GraphQLModule.forRoot<ApolloDriverConfig>({ driver: ApolloDriver, autoSchemaFile: true, fieldResolverEnhancers: enhancers })],
        providers: [UsersResolver, LogGuard],
    })
    class AppModule {}
    return AppModule
}

async function main() {
    for (const enhancers of [[], ["guards"]] as const) {
        calls.length = 0
        const http = await testApp(makeModule([...enhancers]))
        await http.post("/graphql", { query: "{ me { name email } }" })
        console.log(`fieldResolverEnhancers: ${JSON.stringify(enhancers)} -> guard chaqirildi:`, calls)
        await http.close()
    }
}
