import { CanActivate, Controller, ExecutionContext, Get, Injectable, Module } from "@nestjs/common"
import { APP_GUARD } from "@nestjs/core"
import { ApolloDriver, ApolloDriverConfig } from "@nestjs/apollo"
import { GqlContextType, GqlExecutionContext, GraphQLModule, Query, Resolver } from "@nestjs/graphql"

@Injectable()
class ApiKeyGuard implements CanActivate {
    canActivate(ctx: ExecutionContext) {
        const type = ctx.getType<GqlContextType>()
        const req = type === "graphql" ? GqlExecutionContext.create(ctx).getContext().req : ctx.switchToHttp().getRequest()
        const key = req.headers["x-api-key"]
