import { Module } from "@nestjs/common"
import { ApolloDriver, ApolloDriverConfig } from "@nestjs/apollo"
import { Args, CustomScalar, Field, GraphQLModule, Int, ObjectType, Query, Resolver, Scalar } from "@nestjs/graphql"
import { Kind, ValueNode } from "graphql"

@Scalar("DateOnly", () => Date)
class DateOnlyScalar implements CustomScalar<string, Date> {
    description = "Faqat sana: YYYY-MM-DD"
    parseValue(value: string) { return new Date(value) }
    serialize(value: Date) { return value.toISOString().slice(0, 10) }
    parseLiteral(ast: ValueNode) { return ast.kind === Kind.STRING ? new Date(ast.value) : null }
}

@ObjectType()
class Student {
    @Field() name: string
    @Field() birthday: Date          // Date -> DateOnly skalyari
}

@Resolver()
class StudentsResolver {
    @Query(() => Student) student() { return { name: "Ali", birthday: new Date("2005-03-21T00:00:00Z") } }
    @Query(() => Int) yearOf(@Args("date") date: Date) { return date.getUTCFullYear() }
}

@Module({ imports: [GraphQLModule.forRoot<ApolloDriverConfig>({ driver: ApolloDriver, autoSchemaFile: true })], providers: [DateOnlyScalar, StudentsResolver] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.post("/graphql", { query: '{ student { name birthday } yearOf(date: "1999-12-31") }' })
    await http.post("/graphql", { query: "query($d: DateOnly!) { yearOf(date: $d) }", variables: { d: "2026-01-01" } })
    await http.close()
}
main()

