import { Module, ValidationPipe } from "@nestjs/common"
import { ApolloDriver, ApolloDriverConfig } from "@nestjs/apollo"
import { Args, Field, GraphQLModule, InputType, Int, Mutation, Query, Resolver } from "@nestjs/graphql"
import { Type } from "class-transformer"
import { ArrayMinSize, IsInt, MinLength, ValidateNested, Min } from "class-validator"

@InputType()
class LineInput {
    @Field() @MinLength(2) item: string
    @Field(() => Int) @IsInt() @Min(1) qty: number
}

@InputType()
class OrderInput {
    @Field() @MinLength(3) customer: string
    @Field(() => [LineInput]) @ArrayMinSize(1) @ValidateNested({ each: true }) @Type(() => LineInput) lines: LineInput[]
}

@Resolver()
class OrdersResolver {
    @Query(() => String) ping() { return "pong" }
    @Mutation(() => String) placeOrder(@Args("input") input: OrderInput) { return `${input.customer}: ${input.lines.length} qator` }
}

@Module({ imports: [GraphQLModule.forRoot<ApolloDriverConfig>({ driver: ApolloDriver, autoSchemaFile: true, includeStacktraceInErrorResponses: false })], providers: [OrdersResolver] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule, app => app.useGlobalPipes(new ValidationPipe()))
    const send = async (input: object) => {
        const res = await fetch((await http.app.getUrl()) + "/graphql", {
            method: "POST", headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ query: "mutation($i: OrderInput!) { placeOrder(input: $i) }", variables: { i: input } }),
        })
        const body = await res.json()
        console.log(body.errors ? body.errors[0].extensions.originalError.message : body.data.placeOrder)
    }
    await send({ customer: "Ali", lines: [{ item: "Non", qty: 2 }] })
    await send({ customer: "Ali", lines: [{ item: "N", qty: 0 }] })
    await http.close()
}
main()

import { Module } from "@nestjs/common"
import { ApolloDriver, ApolloDriverConfig } from "@nestjs/apollo"
import { Extensions, Field, FieldMiddleware, GraphQLModule, ObjectType, Query, Resolver } from "@nestjs/graphql"

// maydonning extensions'ida role bo'lsa, so'rovchining roli mos kelishi shart
const roleGuard: FieldMiddleware = async (ctx, next) => {
    const { info } = ctx
    const required = info.parentType.getFields()[info.fieldName].extensions?.role
    const role = ctx.context.req.headers["x-role"] ?? "user"
    return required && required !== role ? null : next()
}

@ObjectType()
class Employee {
    @Field() name: string

    @Field({ nullable: true, middleware: [roleGuard] })
    @Extensions({ role: "admin" })                             // maxsus metadata
    salary?: string
}

@Resolver()
class StaffResolver {
    @Query(() => Employee) me() { return { name: "Ali", salary: "8 000 000" } }
}

@Module({ imports: [GraphQLModule.forRoot<ApolloDriverConfig>({ driver: ApolloDriver, autoSchemaFile: true })], providers: [StaffResolver] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.post("/graphql", { query: "{ me { name salary } }" })
    await http.post("/graphql", { query: "{ me { name salary } }" }, { "x-role": "admin" })
    await http.close()
}
main()
